    This function implements the binary search algorithm to find a target element in a sorted list.

    Args:
        sorted_list (list): A list of integers sorted in ascending order.
        start_index (int): The starting index of the search in the sorted_list.
        end_index (int): The ending index of the search in the sorted_list.
        target_element (int): The element to be searched in the sorted_list.

    Returns:
        int: The index of the target_element in the sorted_list if found, otherwise -1.
    """

    # Check if inputs are valid
    if not isinstance(sorted_list, list) or not all(isinstance(item, int) for item in sorted_list):
        raise ValueError("Input list must contain only integers.")
    if not isinstance(start_index, int) or not isinstance(end_index, int) or not isinstance(target_element, int):
        raise ValueError("Start index, end index, and target element must be integers.")
    if start_index < 0 or end_index >= len(sorted_list):
        raise ValueError("Start index and end index must be within the bounds of the list.")
    if start_index > end_index:
        raise ValueError("Start index cannot be greater than end index.")

    # Check base case
    if end_index >= start_index:
        mid_index = (end_index + start_index) // 2

        # If element is present at the middle itself
        if sorted_list[mid_index] == target_element:
            return mid_index

        # If element is smaller than mid, then it can only be present in left subarray
        elif sorted_list[mid_index] > target_element:
            return binary_search(sorted_list, start_index, mid_index - 1, target_element)

        # Else the element can only be present in right subarray
        else:
            return binary_search(sorted_list, mid_index + 1, end_index, target_element)

    else:
        # Element is not present in array
        return -1
